#include "vk_vka1.h"
#include <stdbool.h>
#include <string.h>

#define HEADER_SIZE 56u
#define ENTRY_SIZE 12u
#define MAX_WIDTH 428u
#define MAX_HEIGHT 142u

typedef struct { uint32_t h[8]; uint64_t bits; uint8_t block[64]; size_t used; } sha256_t;
static const uint32_t K[64]={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
static uint32_t rr(uint32_t x,unsigned n){return(x>>n)|(x<<(32-n));}
static void sha_block(sha256_t*s,const uint8_t*b){uint32_t w[64],a,bv,c,d,e,f,g,h;for(unsigned i=0;i<16;i++)w[i]=(uint32_t)b[i*4]<<24|(uint32_t)b[i*4+1]<<16|(uint32_t)b[i*4+2]<<8|b[i*4+3];for(unsigned i=16;i<64;i++){uint32_t x=w[i-15],y=w[i-2];w[i]=(rr(x,7)^rr(x,18)^(x>>3))+w[i-16]+(rr(y,17)^rr(y,19)^(y>>10))+w[i-7];}a=s->h[0];bv=s->h[1];c=s->h[2];d=s->h[3];e=s->h[4];f=s->h[5];g=s->h[6];h=s->h[7];for(unsigned i=0;i<64;i++){uint32_t t1=h+(rr(e,6)^rr(e,11)^rr(e,25))+((e&f)^((~e)&g))+K[i]+w[i],t2=(rr(a,2)^rr(a,13)^rr(a,22))+((a&bv)^(a&c)^(bv&c));h=g;g=f;f=e;e=d+t1;d=c;c=bv;bv=a;a=t1+t2;}s->h[0]+=a;s->h[1]+=bv;s->h[2]+=c;s->h[3]+=d;s->h[4]+=e;s->h[5]+=f;s->h[6]+=g;s->h[7]+=h;}
static void sha_init(sha256_t*s){const uint32_t h[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};memcpy(s->h,h,sizeof h);s->bits=0;s->used=0;}
static void sha_update(sha256_t*s,const uint8_t*p,size_t n){s->bits+=(uint64_t)n*8;while(n){size_t take=64-s->used;if(take>n)take=n;memcpy(s->block+s->used,p,take);s->used+=take;p+=take;n-=take;if(s->used==64){sha_block(s,s->block);s->used=0;}}}
static void sha_final(sha256_t*s,uint8_t out[32]){uint64_t bits=s->bits;s->block[s->used++]=0x80;if(s->used>56){memset(s->block+s->used,0,64-s->used);sha_block(s,s->block);s->used=0;}memset(s->block+s->used,0,56-s->used);for(unsigned i=0;i<8;i++)s->block[63-i]=(uint8_t)(bits>>(i*8));sha_block(s,s->block);for(unsigned i=0;i<8;i++){out[i*4]=(uint8_t)(s->h[i]>>24);out[i*4+1]=(uint8_t)(s->h[i]>>16);out[i*4+2]=(uint8_t)(s->h[i]>>8);out[i*4+3]=(uint8_t)s->h[i];}}
static uint16_t r16(const uint8_t*p){return(uint16_t)p[0]|(uint16_t)p[1]<<8;}static uint32_t r32(const uint8_t*p){return(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static bool add32(uint32_t a,uint32_t b,uint32_t*out){if(a>UINT32_MAX-b)return false;*out=a+b;return true;}
static vk_vka1_result_t entry(const uint8_t*bytes,size_t length,uint16_t index,vk_vka1_frame_info_t*f){if(!bytes||!f||length<HEADER_SIZE)return VK_VKA1_INVALID;uint16_t count=r16(bytes+12);if(index>=count)return VK_VKA1_RANGE;size_t base=HEADER_SIZE+(size_t)index*ENTRY_SIZE;if(base+ENTRY_SIZE>length)return VK_VKA1_RANGE;f->offset=r32(bytes+base);f->encoded_length=r32(bytes+base+4);f->duration_ms=r16(bytes+base+8);f->encoding=(vk_vka1_encoding_t)bytes[base+10];if(bytes[base+11]!=0||(f->encoding!=VK_VKA1_RAW&&f->encoding!=VK_VKA1_ROW_RLE))return VK_VKA1_INVALID;return VK_VKA1_OK;}
static vk_vka1_result_t validate_rle(const uint8_t*p,size_t n,uint16_t width,uint16_t height){size_t pos=0;for(uint16_t y=0;y<height;y++){uint32_t row=0;bool prior=false;uint16_t prior_pixel=0;while(row<width){if(n-pos<4)return VK_VKA1_RLE;uint16_t count=r16(p+pos),pixel=r16(p+pos+2);pos+=4;if(count==0||count>width-row||(prior&&pixel==prior_pixel))return VK_VKA1_RLE;row+=count;prior=true;prior_pixel=pixel;}}return pos==n&&n<(size_t)width*height*2?VK_VKA1_OK:VK_VKA1_RLE;}
static bool raw_is_canonical(const uint8_t*p,uint16_t width,uint16_t height){size_t runs=0;for(uint16_t y=0;y<height;y++){uint16_t x=0;while(x<width){uint16_t pixel=r16(p+((size_t)y*width+x)*2);x++;while(x<width&&r16(p+((size_t)y*width+x)*2)==pixel)x++;runs++;}}return runs*4>=(size_t)width*height*2;}

vk_vka1_result_t vk_vka1_validate(const uint8_t*bytes,size_t length,const vk_vka1_limits_t*limits,vk_vka1_info_t*info){if(!bytes||!limits||!info||length<68||length>limits->max_container_bytes)return VK_VKA1_INVALID;if(memcmp(bytes,"VKA1",4)||bytes[4]<1||bytes[4]>3||bytes[5]!=1||(bytes[6]&~3u)||bytes[7]!=0)return VK_VKA1_INVALID;uint16_t width=r16(bytes+8),height=r16(bytes+10),frames=r16(bytes+12),header=r16(bytes+14);if(width<1||width>MAX_WIDTH||height<1||height>MAX_HEIGHT||frames<1||frames>limits->max_frames)return VK_VKA1_LIMIT;uint32_t pixels=(uint32_t)width*height,decoded=pixels*2;if(decoded>limits->max_decoded_bytes||r32(bytes+16)!=decoded)return VK_VKA1_LIMIT;uint32_t table=(uint32_t)frames*ENTRY_SIZE,expected_header;if(!add32(HEADER_SIZE,table,&expected_header)||header!=expected_header||r32(bytes+20)!=length)return VK_VKA1_INVALID;
 uint8_t digest[32],zero[32]={0};sha256_t s;sha_init(&s);sha_update(&s,bytes,24);sha_update(&s,zero,32);sha_update(&s,bytes+56,length-56);sha_final(&s,digest);if(memcmp(digest,bytes+24,32))return VK_VKA1_HASH;
 uint32_t expected=header;uint8_t bits=0;for(uint16_t i=0;i<frames;i++){vk_vka1_frame_info_t f;if(entry(bytes,length,i,&f)!=VK_VKA1_OK)return VK_VKA1_INVALID;if(f.offset!=expected||f.encoded_length==0||!add32(expected,f.encoded_length,&expected)||expected>length)return VK_VKA1_RANGE;bits|=f.encoding==VK_VKA1_RAW?1:2;if(f.encoding==VK_VKA1_RAW&&(f.encoded_length!=decoded||!raw_is_canonical(bytes+f.offset,width,height)))return VK_VKA1_RANGE;if(f.encoding==VK_VKA1_ROW_RLE){vk_vka1_result_t result=validate_rle(bytes+f.offset,f.encoded_length,width,height);if(result!=VK_VKA1_OK)return result;}if(bytes[4]==VK_VKA1_ANIMATION){if(f.duration_ms==0||f.duration_ms<limits->min_frame_ms||f.duration_ms>limits->max_frame_ms)return VK_VKA1_INVALID;}else if(f.duration_ms!=0)return VK_VKA1_INVALID;}if(expected!=length||bits!=bytes[6])return VK_VKA1_RANGE;if((bytes[4]==VK_VKA1_IMAGE||bytes[4]==VK_VKA1_GLYPH_BITMAP)&&frames!=1)return VK_VKA1_INVALID;
 info->kind=(vk_vka1_kind_t)bytes[4];info->width=width;info->height=height;info->frame_count=frames;info->decoded_bytes_per_frame=decoded;memcpy(info->sha256,bytes+24,32);return VK_VKA1_OK;}
vk_vka1_result_t vk_vka1_frame_info(const uint8_t*b,size_t n,uint16_t i,vk_vka1_frame_info_t*f){return entry(b,n,i,f);}
vk_vka1_result_t vk_vka1_decode_frame(const uint8_t*b,size_t n,uint16_t i,uint16_t*pixels,size_t cap){if(!b||!pixels||n<68)return VK_VKA1_INVALID;uint16_t width=r16(b+8),height=r16(b+10);size_t need=(size_t)width*height;if(cap<need)return VK_VKA1_LIMIT;vk_vka1_frame_info_t f;vk_vka1_result_t result=entry(b,n,i,&f);if(result!=VK_VKA1_OK||f.offset>n||f.encoded_length>n-f.offset)return VK_VKA1_RANGE;const uint8_t*p=b+f.offset;if(f.encoding==VK_VKA1_RAW){if(f.encoded_length!=need*2)return VK_VKA1_RANGE;for(size_t x=0;x<need;x++)pixels[x]=r16(p+x*2);return VK_VKA1_OK;}size_t pos=0,out=0;for(uint16_t y=0;y<height;y++){size_t row=0;bool prior=false;uint16_t prev=0;while(row<width){if(f.encoded_length-pos<4)return VK_VKA1_RLE;uint16_t count=r16(p+pos),pixel=r16(p+pos+2);pos+=4;if(count==0||count>width-row||(prior&&pixel==prev))return VK_VKA1_RLE;for(uint16_t c=0;c<count;c++)pixels[out++]=pixel;row+=count;prior=true;prev=pixel;}}return pos==f.encoded_length?VK_VKA1_OK:VK_VKA1_RLE;}
